import re, os, glob
missing, checked = [], 0
naked = []
for d in ['plan', 'action-steps']:
    for f in glob.glob(d + '/**/*.md', recursive=True):
        base = os.path.dirname(f)
        text = open(f).read()
        refs = [m.group(1) for m in re.finditer(r'\]\(([^)#\s]+?\.md)(#[^)]*)?\)', text)
                 if not m.group(1).startswith(('http', '#'))]
        refs += [m.group(1) for m in re.finditer(r'`((?:plan|action-steps|specs|data|results|src)/[A-Za-z0-9_./-]+?\.md)`', text)]
        for p in refs:
            if re.search(r'^results/|/results/', p):
                continue
            checked += 1
            if p.startswith('../'):
                ok = os.path.exists(os.path.normpath(os.path.join(base, p)))
            else:
                ok = os.path.exists(os.path.normpath(os.path.join(base, p))) or os.path.exists(os.path.normpath(p))
            if not ok:
                missing.append((f, p))
        # naked sibling refs in If-stuck sections
        if d == 'action-steps' and not f.endswith('README.md'):
            sec = re.search(r'## If stuck\n(.*?)(?=\n## |\Z)', text, re.S)
            if sec:
                for m in re.finditer(r'`\s*([A-Za-z0-9_-]+\.md)`', sec.group(1)):
                    if not m.group(1).startswith(('plan/', 'action-steps/')):
                        naked.append((f, m.group(1)))
print(f"links checked={checked} missing={len(missing)} naked-if-stuck-refs={len(naked)}")
for f, p in missing + [(f, p + ' (naked)') for f, p in naked]:
    print("PROBLEM:", p, "<-", f)
EOF
